import {it,expect} from 'vitest';
import {courses} from '../../src/games/mini-golf/ultimate/courses';
import {GolfPhysics} from '../../src/games/mini-golf/ultimate/GolfPhysics';
const lane=(1920-196)/6,c=(i:number)=>28+i*(lane+28)+lane/2;
const routes=[[[c(0),220],[c(1)+110,220],[c(1)+110,670],[c(1)-100,670],[c(1)-100,950],[680,950],[680,220],[1235,220],[1235,950],[c(4),950],[c(4),220],[c(5)-120,220],[c(5)-120,942],[c(5),942]],[[220,990],[220,220],[520,220],[520,970],[910,970],[910,220],[910,150],[1340,150],[1340,930],[1760,930],[1760,220],[1560,200]],[[1100,990],[1810,990],[1840,700,1265,340],[290,340],[290,590],[700,600,1205,600],[1400,575]],[[520,980],[790,960],[1080,960],[1080,570],[1000,570],[1260,570],[1260,220],[1810,200],[1810,950],[1770,660],[1770,570],[1560,575]]];
function clone(w:GolfPhysics){const n=new GolfPhysics(w.course,w.difficulty,()=>.9);Object.assign(n.ball,w.ball);n.lastShot={...w.lastShot};n.strokes=w.strokes;const d=n.dynamics,s=w.dynamics;d.time=s.time;d.gate=s.gate;d.plates=[...s.plates];d.doors=[...s.doors];d.planks=[...s.planks];d.portalCooldown=s.portalCooldown;d.ufo={...s.ufo};return n;}
for(let course=0;course<4;course++)it(`full course route ${course+1}`,()=>{let w=new GolfPhysics(courses[course],0,()=>.9);const shots:number[][]=[];for(const [tx,ty,gx=tx,gy=ty] of routes[course]){for(let attempt=0;attempt<3;attempt++){if(w.status==='won')break;const distance=Math.hypot(w.ball.x-tx,w.ball.y-ty);if(distance<22)break;const angle=Math.atan2(ty-w.ball.y,tx-w.ball.x);let best:GolfPhysics|undefined,bestCost=Infinity,bestShot:number[]=[];for(const wait of (course===1?[0,.6,1.2,2,3,4,5,6]:[0,.6,1.2,2]))for(const da of [0,-.03,.03,-.08,.08,-.18,.18])for(let power=60;power<=650;power+=15){const trial=clone(w);for(let i=0;i<wait*240;i++)trial.tick(1/240);if(!trial.shootable)continue;const vx=Math.cos(angle+da)*power,vy=Math.sin(angle+da)*power;trial.shoot(vx,vy);for(let i=0;i<240*12;i++){trial.tick(1/240);if(trial.stopped||trial.status!=='playing')break;}const cost=trial.status==='won'?-1e6:Math.hypot(trial.ball.x-gx,trial.ball.y-gy)+(trial.recoveries?1e5:0)+(!trial.stopped?1e4:0);if(cost<bestCost){bestCost=cost;best=trial;bestShot=[wait,vx,vy];}if(cost<2)break;}if(!best||bestCost>=distance-1)break;w=best;shots.push(bestShot);console.log(course,'target',tx,ty,'at',w.ball.x,w.ball.y,'stroke',w.strokes,w.status);}}
 console.log('ROUTE',course,JSON.stringify(shots));expect(w.status).toBe('won');},120000);
